const triggerItems = $items("When Executed by Another Workflow", 0, 0);

if (!triggerItems || !triggerItems.length) {
  throw new Error("Missing input from When Executed by Another Workflow");
}

const trigger = triggerItems[0].json || {};
const ctx = $json || {};

const messages = Array.isArray(ctx.messages) ? ctx.messages : [];

let baseSystem =
  "You are the customer support and sales assistant for this business. Be helpful, accurate, and speak as the business.";

const contextOk =
  messages.length > 0 &&
  messages[0] &&
  typeof messages[0].content === "string" &&
  messages[0].content.trim().length > 0;

if (contextOk) {
  baseSystem = messages[0].content;
}

const customerTurns = messages
  .slice(1)
  .filter(
    (m) =>
      m &&
      m.role === "user" &&
      typeof m.content === "string" &&
      m.content.trim()
  )
  .map((m) => m.content);

const currentMessage =
  typeof trigger.current_message === "string"
    ? trigger.current_message
    : "";

const currentStep = trigger.current_step || null;

const operatingRules = [
  "",
  "## How you operate",
  "- You have tools. Use get_business_facts for ANY question about branches, locations, address, phone, or working hours. Use search_business_knowledge for ANY question about products, menu, prices, services, policies, offers, or how things work.",
  "- The \"RELEVANT KNOWLEDGE BASE EXCERPTS\" section in the context above is THIS turn's authoritative lookup for products, services, prices, durations, policies, offers and availability. If an excerpt there directly answers the customer's question, answer ONLY from it and add NO detail (quantity, weight, size, portion, ingredient, material, type/species, variant, option, etc.) that is not written there. If that section is missing or does not cover the question, call search_business_knowledge ONCE with the question rephrased as a sharper search query. If that search still returns nothing, tell the customer that detail is not confirmed and offer to check with / connect them to the team. Never answer these factual topics from general knowledge or from memory. (Location, working hours and phone still come from get_business_facts - unchanged, and never guess there either, and never say we do not have X when you simply do not know.)",
  "- get_business_facts returns locations_guidance. Obey it exactly. If the location list is not confirmed complete, an unlisted location is UNKNOWN - never say our only branch is X.",
  "- Customer wants a human, or an unresolved complaint -> request_human_handover. Customer gives a name or phone -> save_lead. Customer wants to order -> start_order, then gather items and contact info, then save_lead and request_human_handover so a teammate finalizes it. Customer is done -> close_conversation with confirmed false; the system will ask them to confirm.",
  "- Booking requests, and requests to be sent a file or menu image: answer helpfully with what you have and offer to connect them with the team. Do not invent a booking. Do not claim a file was sent.",
  "- Reply in the customer language (Arabic, Palestinian-Levantine colloquial, English, or mixed). Speak AS the business (we, our). Never mention tools, steps, or that you are an AI.",
  "- Ask at most ONE short clarifying question, and only when genuinely ambiguous.",
  "- End every reply with a new line exactly: #intent: <one of greeting|knowledge|price|order|booking|asset_request|support|complaint|human_request|lead|closing|unknown>"
].join("\n");

const historyBlock = customerTurns.length
  ? [
      "",
      "## Conversation so far (the customer's previous messages only)",
      ...customerTurns.map((t) => "- " + t)
    ]
  : [];

const stepHint = currentStep
  ? [
      "",
      "## Current step: " +
        currentStep +
        (
          currentStep === "waiting_for_contact"
            ? " - the customer was asked for their name and phone; if this message contains them, call save_lead."
            : ""
        )
    ]
  : [];

const degradedBlock = contextOk
  ? []
  : [
      "",
      "## Business context unavailable this turn",
      "- The authoritative business profile and knowledge base could not be loaded.",
      "- Do NOT state any specific price, product detail, branch, address, or opening time.",
      "- Use your tools; if a tool cannot answer, tell the customer you will check with the team and follow up. Never guess."
    ];

return [
  {
    json: {
      conversation_id: trigger.conversation_id || null,
      message_id: trigger.message_id || null,
      channel: trigger.channel || null,
      current_message: currentMessage,
      context_ok: contextOk,
      system_message: [
        baseSystem,
        operatingRules,
        ...degradedBlock,
        ...historyBlock,
        ...stepHint
      ].join("\n")
    }
  }
];

