parameters.jsCode:
const agent = $json || {};

const triggerItems = $items("When Executed by Another Workflow", 0, 0);
const trigger =
  triggerItems && triggerItems.length
    ? (triggerItems[0].json || {})
    : {};

// --------------------------------------------------
// Extract reply
// --------------------------------------------------

let raw = "";

if (agent.output !== undefined && agent.output !== null) {
  raw = agent.output;
} else if (agent.text !== undefined && agent.text !== null) {
  raw = agent.text;
} else if (agent.response !== undefined && agent.response !== null) {
  raw = agent.response;
}

if (typeof raw === "object") {
  try {
    raw = JSON.stringify(raw);
  } catch (e) {
    raw = "";
  }
}

const text = String(raw || "").trim();

// --------------------------------------------------
// Extract intent marker  (QW4 — hardened)
//   * use the LAST "#intent:" occurrence in the reply
//   * tolerate ANY trailing text after it (punctuation, emoji, a stray
//     extra line) — the marker and everything after it is removed
//   * map a few near-miss synonyms the model still emits from an older
//     instruction list back onto the 12-value taxonomy
// --------------------------------------------------

const INTENT_MARKER = /#intent:\s*([a-z_]+)/gi;

let lastMatch = null;
for (const m of text.matchAll(INTENT_MARKER)) {
  lastMatch = m;
}

let modelIntent = lastMatch ? String(lastMatch[1]).toLowerCase() : "unknown";

// Cut everything from the FIRST surviving "#intent:" token to the end, so
// an earlier stray marker (before the last one) is removed from the reply
// too — never shown to the customer.
let reply = (lastMatch ? text.slice(0, lastMatch.index) : text)
  .replace(/#intent:[\s\S]*$/i, "")
  .trim();

const INTENT_ALIASES = {
  pricing: "price",
  prices: "price",
  knowledge_base: "knowledge"
};
if (INTENT_ALIASES[modelIntent]) {
  modelIntent = INTENT_ALIASES[modelIntent];
}

const TAXONOMY = [
  "greeting",
  "knowledge",
  "price",
  "order",
  "booking",
  "asset_request",
  "support",
  "complaint",
  "human_request",
  "lead",
  "closing",
  "unknown"
];

if (!TAXONOMY.includes(modelIntent)) {
  modelIntent = "unknown";
}

// --------------------------------------------------
// Read tool executions
// --------------------------------------------------

const steps = Array.isArray(agent.intermediateSteps)
  ? agent.intermediateSteps
  : [];

const toolsUsed = steps
  .map((step) => {
    if (step?.action?.tool) {
      return step.action.tool;
    }

    if (step?.tool) {
      return step.tool;
    }

    return null;
  })
  .filter(Boolean);

// --------------------------------------------------
// Deterministic intent/action from executed tools
// --------------------------------------------------

let action = null;
let deterministicIntent = null;

if (toolsUsed.includes("request_human_handover")) {
  action = "human_handover";
  deterministicIntent = "human_request";
}
else if (toolsUsed.includes("close_conversation")) {
  action = "close_needs_confirmation";
  deterministicIntent = "closing";
}
else if (toolsUsed.includes("save_lead")) {
  action = "lead_saved";
  deterministicIntent = "lead";
}
else if (
  toolsUsed.includes("start_order") ||
  toolsUsed.includes("continue_order")
) {
  action = "order_in_progress";
  deterministicIntent = "order";
}

// --------------------------------------------------
// Resolve final intent
// --------------------------------------------------

let finalIntent = deterministicIntent || modelIntent;

// Business facts tool was used but model returned unknown
if (
  finalIntent === "unknown" &&
  toolsUsed.includes("get_business_facts")
) {
  finalIntent = "knowledge";
}

// Knowledge tool was used but model returned unknown
if (
  finalIntent === "unknown" &&
  toolsUsed.includes("search_business_knowledge")
) {
  finalIntent = "knowledge";
}

// Preserve price classification when knowledge search was used
if (
  modelIntent === "price"
) {
  finalIntent = "price";
}

// --------------------------------------------------
// Deterministic keyword fallback (NO extra LLM call).
// Only runs when nothing else resolved an intent: the model emitted no
// usable #intent marker AND no executed tool implied one. Never overrides
// a valid model- or tool-derived intent.
// --------------------------------------------------

if (finalIntent === "unknown") {
  const cust = String(trigger.current_message || "").toLowerCase();

  const matchAny = (arr) =>
    arr.some((k) => {
      if (/[a-z]/i.test(k)) {
        const esc = k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        return new RegExp("(^|[^a-z])" + esc + "([^a-z]|$)", "i").test(cust);
      }
      return cust.indexOf(k) !== -1;
    });

  const KW_HUMAN = [
    "موظف", "مندوب", "خدمة العملاء", "خدمه العملاء",
    "حد حقيقي", "حدا حقيقي", "بشر", "ادمي", "آدمي",
    "بدي احكي", "بدي أحكي", "احكي مع حدا", "أحكي مع حدا",
    "اتواصل مع حدا", "اكلم حدا", "أكلم حدا",
    "representative", "agent", "human", "real person", "customer service",
    "talk to someone", "talk to a person", "speak to someone", "speak to a person"
  ];
  const KW_PRICE = [
    "سعر", "اسعار", "أسعار", "بكم", "بقديش", "قديش", "كم سعر",
    "التكلفة", "التكلفه", "كلفة", "كلفه",
    "price", "prices", "pricing", "cost", "how much", "rate", "rates", "quote"
  ];
  const KW_KNOW = [
    "وين", "فين", "موقع", "موقعكم", "لوكيشن", "فرع", "فروع",
    "عنوان", "عنوانكم", "دوام", "الدوام", "اوقات", "أوقات",
    "ساعات العمل", "متى تفتح", "متى بتفتح", "متى بتسكر",
    "بتفتحو", "بتسكرو", "امتى بتفتح",
    "location", "address", "where are you", "where is", "branch", "branches",
    "working hours", "opening hours", "open today", "what time", "hours"
  ];
  const KW_GREET = [
    "مرحبا", "مرحبتين", "السلام عليكم", "اهلا", "أهلا", "هاي",
    "هلا", "هلو", "صباح الخير", "مساء الخير", "كيفك",
    "hi", "hello", "hey", "good morning", "good evening", "good afternoon"
  ];
  const KW_CLOSE = [
    "شكرا", "شكرًا", "شكراً", "يسلمو", "مشكور", "مشكورة", "تسلم",
    "خلص", "بس هيك", "هيك بس", "تمام شكرا", "الله يعطيك العافية",
    "thanks", "thank you", "thx", "that's all", "thats all", "bye", "goodbye", "see you"
  ];

  if (matchAny(KW_HUMAN)) {
    finalIntent = "human_request";
  } else if (matchAny(KW_PRICE)) {
    finalIntent = "price";
  } else if (matchAny(KW_KNOW)) {
    finalIntent = "knowledge";
  } else if (matchAny(KW_CLOSE)) {
    finalIntent = "closing";
  } else if (matchAny(KW_GREET)) {
    finalIntent = "greeting";
  }
}

// --------------------------------------------------
// Was lifecycle action already performed by a tool?
// --------------------------------------------------

const handoverAlreadyExecuted =
  toolsUsed.includes("request_human_handover");

const alreadyRecorded =
  Boolean(deterministicIntent);

// --------------------------------------------------
// Extract lifecycle values from tool observations
// --------------------------------------------------

let conversationStatus = null;
let currentStep = null;
let quickReplyAction = null;

for (const step of steps) {

  let observation = step?.observation;

  if (typeof observation === "string") {
    try {
      observation = JSON.parse(observation);
    } catch (e) {
      observation = null;
    }
  }

  if (
    observation &&
    typeof observation === "object"
  ) {

    if (observation.conversation_status) {
      conversationStatus =
        observation.conversation_status;
    }

    if (observation.current_step) {
      currentStep =
        observation.current_step;
    }

    if (observation.quick_reply_action) {
      quickReplyAction =
        observation.quick_reply_action;
    }
  }
}

// --------------------------------------------------
// Output
// --------------------------------------------------

return [
  {
    json: {
      conversation_id:
        trigger.conversation_id || null,

      client_id:
        trigger.client_id || null,

      message_id:
        trigger.message_id || null,

      reply,

      intent: finalIntent,

      action,

      already_recorded: alreadyRecorded,

      handover_already_executed:
        handoverAlreadyExecuted,

      conversation_status:
        conversationStatus,

      current_step:
        currentStep,

      quick_reply_action:
        quickReplyAction
    }
  }
];

// Base carries every Resolve Intent field plus must_handover /
// already_recorded (Force Required Action spreads Resolve Intent).
const fraItems = $items("Force Required Action", 0, 0);
let src = (fraItems && fraItems.length ? fraItems[0].json : null) || {};

if (!src || Object.keys(src).length === 0) {
  const ri = $items("Resolve Intent", 0, 0);
  src = (ri && ri.length ? ri[0].json : {}) || {};
}

let intent = src.intent || "unknown";
let action = src.action || null;
let conversationStatus = src.conversation_status || null;
let currentStep = src.current_step || null;
const quickReplyAction = src.quick_reply_action || null;
const reply = src.reply || "";

// --- Detect a completed human handover -------------------------------
// Path 1: the agent executed the request_human_handover tool itself.
const toolHandover = src.handover_already_executed === true;

// Path 2: the deterministic Force Human Handover HTTP node ran.
let forcedAttempted = src.must_handover === true;
let forcedOk = false;
try {
  const fh = $items("Force Human Handover", 0, 0);
  if (fh && fh.length) {
    const resp = fh[0].json || {};
    forcedAttempted = true;
    forcedOk =
      resp.error === undefined &&
      (resp.ok === true ||
        resp.action === "human_handover" ||
        resp.conversation_status === "waiting_human");
  }
} catch (e) {
  // node did not run on this branch
}

const handoverDone = toolHandover || forcedOk;

if (handoverDone) {
  intent = "human_request";
  action = "human_handover";
  conversationStatus = "waiting_human";
} else if (forcedAttempted && intent === "human_request") {
  // Handover was required but could not be confirmed this turn. Still
  // surface the intent so the parent non-downgrade guard parks the
  // conversation in waiting_human rather than letting AI keep replying.
  action = "human_handover";
  conversationStatus = "waiting_human";
}

// close_conversation(confirmed:true) already surfaces via
// src.conversation_status / src.current_step from the tool observation.

return [
  {
    json: {
      reply,
      intent,
      action,
      quick_reply_action: quickReplyAction,
      conversation_status: conversationStatus,
      current_step: currentStep,
      handover_done: handoverDone,
      handover_unconfirmed: forcedAttempted && !forcedOk && !toolHandover
    }
  }
];

const r = $json || {};

const mustHandover =
  r.intent === "human_request" &&
  r.handover_already_executed !== true;

// Intent persistence is guaranteed by the backend whenever a lifecycle
// tool runs (agent tool path) OR the deterministic Force Human Handover
// runs (/api/ai-tools request_handover -> handleRequestHandover records
// the human_request intent). In those cases the n8n Record Intent step
// must be skipped to avoid a duplicate message-intent write.
const alreadyRecorded =
  r.already_recorded === true ||
  r.handover_already_executed === true ||
  mustHandover;

return [
  {
    json: {
      ...r,
      must_handover: mustHandover,
      already_recorded: alreadyRecorded
    }
  }
];
